def find_kth_divisor(n: int, k: int) -> int:
    """Find the k-th smallest divisor of n or return -1 if it doesn't exist."""
    divisors = []

    # Find all divisors up to sqrt(n)
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)

    # Sort divisors
    divisors.sort()

    # Return k-th smallest divisor (1-indexed)
    if len(divisors) >= k:
        return divisors[k - 1]
    else:
        return -1

n, k = map(int, input().split())
print(find_kth_divisor(n, k))
"}

