import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    # Degree array
    deg = [len(adj[i]) for i in range(n + 1)]

    # Union-Find to find connected components
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px = find(x)
        py = find(y)
        if px != py:
            parent[py] = px

    # Union all edges
    for i in range(1, n + 1):
        for j in adj[i]:
            if j > i:
                union(i, j)

    # Group by root
    components = {}
    for i in range(1, n + 1):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    # Check each component
    for nodes in components.values():
        size = len(nodes)
        for node in nodes:
            if deg[node] != size - 1:
                print("NO")
                return

    print("YES")

if __name__ == "__main__":
    solve()
"}

