def xor_range(a, b):
    """Compute XOR of all integers from a to b (inclusive)."""
    def xor_upto(n):
        mod = n % 4
        if mod == 0:
            return n
        elif mod == 1:
            return 1
        elif mod == 2:
            return n + 1
        else:  # mod == 3
            return 0

    return xor_upto(b) ^ xor_upto(a - 1)

n = int(input())
xor_sum = 0

for _ in range(n):
    x, m = map(int, input().split())

    # The last dumper is x + m - 1
    last = x + m - 1

    # XOR all values from x to last
    xor_sum ^= xor_range(x, last)

if xor_sum != 0:
    print("tolik")
else:
    print("bolik")
"}

