def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Use a stack that stores elements with their counts
    stack = []
    for num in a:
        if stack and stack[-1][0] == num:
            # Merge equal elements
            count = stack[-1][1] + 1
            if count == 1:
                stack.pop()
                stack.append((num + 1, 1))
            else:
                stack[-1] = (num + 1, count)
        else:
            stack.append((num, 1))

    # Flatten the stack
    result = [x[0] for x in stack]
    print(len(result))
    print(' '.join(map(str, result)))

solve()
"}

