def solve():
    words = input().split()

    # Map from ending to (part of speech, gender)
    ending_to_info = {
        "lios": ("adjective", "masculine"),
        "liala": ("adjective", "feminine"),
        "etr": ("noun", "masculine"),
        "etra": ("noun", "feminine"),
        "initis": ("verb", "masculine"),
        "inites": ("verb", "feminine")
    }

    # Parse each word
    parsed = []
    for word in words:
        if len(word) < 2:
            print("NO")
            return

        # Check for adjective endings
        if len(word) >= 4 and word[-4:] == "lios":
            parsed.append(("adjective", "masculine"))
        elif len(word) >= 5 and word[-5:] == "liala":
            parsed.append(("adjective", "feminine"))

        # Check for noun endings
        elif len(word) >= 3 and word[-3:] == "etr":
            parsed.append(("noun", "masculine"))
        elif len(word) >= 4 and word[-4:] == "etra":
            parsed.append(("noun", "feminine"))

        # Check for verb endings
        elif len(word) >= 5 and word[-5:] == "initis":
            parsed.append(("verb", "masculine"))
        elif len(word) >= 5 and word[-5:] == "inites":
            parsed.append(("verb", "feminine"))

        else:
            print("NO")
            return

    # Check if all words are valid
    if len(parsed) == 0:
        print("NO")
        return

    # If only one word, it's a valid sentence
    if len(parsed) == 1:
        print("YES")
        return

    # Check if it's a valid statement
    genders = [info[1] for info in parsed]
    if len(set(genders)) != 1:
        print("NO")
        return

    parts_of_speech = [info[0] for info in parsed]

    # Check order: adjectives (0+) + noun (1) + verbs (0+)
    noun_count = parts_of_speech.count("noun")
    if noun_count != 1:
        print("NO")
        return

    noun_index = parts_of_speech.index("noun")

    # Check all words before noun are adjectives
    for part in parts_of_speech[:noun_index]:
        if part != "adjective":
            print("NO")
            return

    # Check all words after noun are verbs
    for part in parts_of_speech[noun_index + 1:]:
        if part != "verb":
            print("NO")
            return

    print("YES")

solve()
