import sys

def weird_subtraction_process(a, b):
    while a > 0 and b > 0:
        if a >= 2 * b:
            a -= 2 * b
        elif b >= 2 * a:
            b -= 2 * a
        else:
            break
    return a, b

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    result = weird_subtraction_process(n, m)
    print(f"{result[0]} {result[1]}")

if __name__ == "__main__":
    main()
"}

