def count_good_intervals(s):
    n = len(s)
    total = 0

    # Find all good triples (x, x+k, x+2k)
    triples = []
    for x in range(1, n - 2):
        for k in range(1, n - 2 * x + 1):
            xk = x + k
            x2k = x + 2 * k
            if x2k > n:
                break
            if s[x-1] == s[xk-1] == s[x2k-1]:
                triples.append((x, xk, x2k))

    # Count intervals containing at least one good triple
    # Using inclusion-exclusion
    result = 0

    # Count intervals containing each good triple
    count_single = {}  # (x, x2k) -> count
    for (x, xk, x2k) in triples:
        count = x * (n - x2k + 1)
        count_single[(x, x2k)] = count
        result += count

    # Count intervals containing exactly two good triples
    count_double = 0
    for i, (x1, x1k, x12k) in enumerate(triples):
        for j, (x2, x2k, x22k) in enumerate(triples):
            if i >= j:
                continue
            # Find the intersection of intervals containing both triples
            # Triple 1: l ≤ x1, r ≥ x12k
            # Triple 2: l ≤ x2, r ≥ x22k
            # Intersection: l ≤ min(x1, x2), r ≥ max(x12k, x22k)
            if max(x12k, x22k) > n:
                continue
            overlap_count = min(x1, x2) * (n - max(x12k, x22k) + 1)
            if overlap_count > 0:
                count_double += overlap_count

    # Count intervals containing exactly three good triples
    count_triple = 0
    for i, (x1, x1k, x12k) in enumerate(triples):
        for j, (x2, x2k, x22k) in enumerate(triples):
            if i >= j:
                continue
            for k, (x3, x3k, x32k) in enumerate(triples):
                if i >= k or j >= k:
                    continue
                if max(x12k, x22k, x32k) > n:
                    continue
                overlap_count = min(x1, x2, x3) * (n - max(x12k, x22k, x32k) + 1)
                if overlap_count > 0:
                    count_triple += overlap_count

    # Inclusion-exclusion formula
    # |A1 ∪ A2 ∪ ...| = sum A_i - sum A_i∩A_j + sum A_i∩A_j∩A_k - ...
    result -= count_double
    result += count_triple

    return result

