import sys

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # dp[i][c] = minimum recolors to reach color c at position i
    # c can be 0 (R), 1 (G), 2 (B)
    # Initialize first position
    dp = [[float('inf')] * 3 for _ in range(n)]

    for color_idx, color in enumerate(['R', 'G', 'B']):
        if color != s[0]:
            dp[0][color_idx] = 1
        else:
            dp[0][color_idx] = 0

    # Fill dp table
    for i in range(1, n):
        for prev_color_idx, prev_color in enumerate(['R', 'G', 'B']):
            for curr_color_idx, curr_color in enumerate(['R', 'G', 'B']):
                if prev_color != curr_color:
                    # Can transition from prev to curr
                    cost = 1 if curr_color != s[i] else 0
                    dp[i][curr_color_idx] = min(dp[i][curr_color_idx], dp[i-1][prev_color_idx] + cost)

    # Find minimum recolors overall
    min_recolors = min(dp[n-1])

    # Reconstruct path
    config = [''] * n
    last_color_idx = dp[n-1].index(min_recolors)
    config[-1] = ['R', 'G', 'B'][last_color_idx]

    for i in range(n-2, -1, -1):
        for curr_color_idx, curr_color in enumerate(['R', 'G', 'B']):
            if curr_color == config[i+1]:
                continue
            # Find previous color that gave minimum cost to curr_color
            for prev_color_idx, prev_color in enumerate(['R', 'G', 'B']):
                if prev_color != curr_color and dp[i+1][curr_color_idx] == dp[i][prev_color_idx] + (1 if curr_color != s[i+1] else 0):
                    config[i] = prev_color
                    break

    print(min_recolors)
    print(''.join(config))

if __name__ == "__main__":
    solve()
