    results = []

    for _ in range(T):
        n, x = map(int, input().split())
        s = input().strip()

        cnt0 = s.count('0')
        cnt1 = n - cnt0

        # Balance after one full cycle
        cycle_balance = cnt0 - cnt1

        # Check if there's a prefix with balance x
        prefix_balances = []
        balance = 0
        prefix_balances.append(balance)  # empty prefix

        for ch in s:
            if ch == '0':
                balance += 1
            else:
                balance -= 1
            prefix_balances.append(balance)

        # Check if we can reach balance x
        if cycle_balance == 0:
            # If balance doesn't change, check if any prefix has balance x
            if x in prefix_balances:
                results.append(-1)  # infinite number
            else:
                results.append(0)  # no prefixes
        else:
            # If balance changes, check if x can be achieved
            if x in prefix_balances:
                results.append(1)  # exactly one prefix
            else:
                results.append(0)  # no prefixes

    for res in results:
        print(res)

