import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    k = int(next(it))
    n = int(next(it))

    # Dictionary to store strings and their counts and max beauty
    string_info = {}

    for _ in range(k):
        s = next(it)
        a = int(next(it))

        if s not in string_info:
            string_info[s] = (1, a)  # (count, max_beauty)
        else:
            cnt, max_b = string_info[s]
            string_info[s] = (cnt + 1, max(max_b, a))

    result = 0
    used = set()

    # Process each string
    for s, (cnt, max_b) in string_info.items():
        # If we use this string in a pair, we need its reverse
        s_rev = s[::-1]

        if s in used or s_rev in used:
            continue

        if s_rev in string_info:
            # We can pair s with s_rev
            pairs = min(cnt, string_info[s_rev][0])
            contribution = max_b + string_info[s_rev][1]

            if contribution > 0:
                result += contribution * pairs
                used.add(s)
                used.add(s_rev)
        else:
            # Can't form a pair, just use it alone (if it's symmetric)
            if s == s_rev:
                result += max_b * cnt
                used.add(s)

    print(result)

if __name__ == "__main__":
    solve()
