import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    f = list(map(int, data[2:2+n]))
    w = list(map(int, data[2+n:2+2*n]))

    # For each vertex, we need to find after k steps
    # We'll use binary exponentiation to compute this efficiently
    # For each vertex, we'll compute:
    # - end: where we end up after k steps
    # - sum_path: sum of weights along the path
    # - min_path: minimum weight along the path

