import sys

def is_great(length, lengths):
    """Check if a choice with given length is great"""
    # Check if it's twice shorter than all others
    if all(length <= other_len / 2 for other_len in lengths):
        return True

    # Check if it's twice longer than all others
    if all(length >= 2 * other_len for other_len in lengths):
        return True

    return False

def solve():
    lines = [line.strip() for line in sys.stdin]

    # Extract descriptions (after the prefix)
    descriptions = []
    for line in lines:
        # Remove the prefix 'X.' where X is A, B, C, or D
        if line.startswith('A.'):
            desc = line[2:]
        elif line.startswith('B.'):
            desc = line[2:]
        elif line.startswith('C.'):
            desc = line[2:]
        elif line.startswith('D.'):
            desc = line[2:]
        descriptions.append(desc)

    # Calculate lengths
    lengths = [len(desc) for desc in descriptions]

    # Find great choices
    great_choices = []
    for i, length in enumerate(lengths):
        if is_great(length, lengths):
            great_choices.append(i)

    # Determine the result
    if len(great_choices) == 1:
        return chr(ord('A') + great_choices[0])
    else:
        return 'C'

if __name__ == '__main__':
    print(solve())
