def shortest_path_left_up(n, m, grid):
    """Find the minimum number of magic columns needed to block all paths from basilisk to door."""

    # DP: dp[i][j] = minimum cost to reach (i, j) from (n-1, m-1)
    dp = [[float('inf')] * m for _ in range(n)]
    dp[n-1][m-1] = 0

    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            # Can only move left or up
            if i < n-1 and dp[i+1][j] != float('inf'):
                cost = 0 if grid[i][j] == '.' else 1
                if dp[i][j] > dp[i+1][j] + cost:
                    dp[i][j] = dp[i+1][j] + cost
            if j < m-1 and dp[i][j+1] != float('inf'):
                cost = 0 if grid[i][j] == '.' else 1
                if dp[i][j] > dp[i][j+1] + cost:
                    dp[i][j] = dp[i][j+1] + cost

    return dp[0][0] if dp[0][0] != float('inf') else -1

n, m = map(int, input().split())
grid = [input().strip() for _ in range(n)]

result = shortest_path_left_up(n, m, grid)
print(result)
