import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    leftover = 0
    for i in range(n):
        ai = a[i]

        # Use discount 2 coupons (covers day i and i+1)
        use_coupon = min(leftover, ai)
        ai -= use_coupon
        leftover = min(leftover - use_coupon, ai)

        # If we still need pizzas for day i, use discount 1
        if ai > 0:
            # Check if we can use discount 1
            if ai % 2 == 0:
                ai -= 2 * (ai // 2)
                leftover = ai % 2
            else:
                # Need to use one more discount 2 coupon
                if leftover > 0:
                    ai -= 1
                    leftover -= 1
                elif i + 1 < n:
                    ai -= 1
                    leftover += 1
                    ai -= 2
                else:
                    print("NO")
                    return
        else:
            leftover = 0

    print("YES")

if __name__ == "__main__":
    solve()
