def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Find all pairs of trees with the same appeal
    appeal_map = {}
    for i in range(n):
        appeal_map.setdefault(a[i], []).append(i)

    max_sum = -float('inf')
    best_i = -1
    best_j = -1
    k = 0

    # Try all pairs (i, j) where i < j and a[i] == a[j]
    for value in appeal_map:
        positions = appeal_map[value]
        for idx in range(len(positions)):
            for idy in range(idx + 1, len(positions)):
                i = positions[idx]
                j = positions[idy]

                # Keep all trees with positive appeal that are between i and j (inclusive)
                current_sum = 0

                for idx in range(i, j + 1):
                    if a[idx] > 0:
                        current_sum += a[idx]
                        k += 1

                # Check if this is the best solution
                if current_sum > max_sum:
                    max_sum = current_sum
                    best_i = i
                    best_j = j

    # The result is max_sum, and the number of trees to cut down is n - k
    print(max_sum, n - k)

    # Output the trees to cut down
    # Keep all trees with positive appeal that are between best_i and best_j
    kept = set()
    for idx in range(best_i, best_j + 1):
        if a[idx] > 0:
            kept.add(idx + 1)  # 1-indexed

    # Output all tree numbers that are NOT kept
    for i in range(1, n + 1):
        if i not in kept:
            print(i)

