from collections import defaultdict

def solve():
    k, n = map(int, input().split())
    groups = defaultdict(list)

    # Group strings by their content
    for _ in range(k):
        s, a = input().split()
        groups[s].append(int(a))

    # Sort each group by beauty
    for s in groups:
        groups[s].sort()

    # Find the best palindrome string that can be used in the middle
    middle_candidate = -1000000000  # A very negative value
    for s in groups:
        if s == s[::-1]:  # Check if string is a palindrome
            if groups[s]:
                middle_candidate = max(middle_candidate, groups[s][-1])

    # Find the best mirror pairs
    max_pair_beauty = 0
    used_strings = set()

    # Consider all possible pairs
    for s in groups:
        if s in used_strings:
            continue

        reversed_s = s[::-1]
        if reversed_s != s and reversed_s in groups and reversed_s not in used_strings:
            # Try all combinations for this pair
            for i in range(len(groups[s])):
                for j in range(len(groups[reversed_s])):
                    total = groups[s][i] + groups[reversed_s][j]

                    # If this is better, update
                    if total > max_pair_beauty:
                        max_pair_beauty = total
                        used_strings.add(s)
                        used_strings.add(reversed_s)

    total = max_pair_beauty

    # Add middle string if it's beautiful
    if middle_candidate > 0:
        total += middle_candidate

    print(max(total, 0))

solve()
