def solve():
    n = int(input())
    s = input().strip()

    # dp[i][c] = minimum recolors to make first i lamps diverse ending with color c
    # c can be 0, 1, 2 for 'R', 'G', 'B'
    INF = float('inf')
    dp = [[INF] * 3 for _ in range(n + 1)]

    # Base case: no lamps, no recolors
    for c in range(3):
        dp[0][c] = 0

    # Fill DP table
    for i in range(1, n + 1):
        for c in range(3):
            # Try all previous colors that are different
            for prev_c in range(3):
                if prev_c != c:
                    dp[i][c] = min(dp[i][c], dp[i-1][prev_c] + (s[i-1] != chr(ord('R') + c)))

    # Find minimum recolors
    min_recolors = min(dp[n])

    # Reconstruct the path
    result = [''] * n
    cur_color = dp[n].index(min_recolors)
    result[-1] = chr(ord('R') + cur_color)

    for i in range(n - 1, 0, -1):
        for prev_c in range(3):
            if prev_c != cur_color:
                if dp[i][cur_color] == dp[i-1][prev_c] + (s[i-1] != chr(ord('R') + cur_color)):
                    result[i-1] = chr(ord('R') + prev_c)
                    cur_color = prev_c
                    break

    print(min_recolors)
    print(''.join(result))

solve()
