# 2D difference array (1-indexed)
diff = [[0] * (n + 2) for _ in range(n + 2)]

for x in range(n):
    for k in range(1, n - x):
        if x + 2*k < n and s[x] == s[x+k] and s[x+k] == s[x+2*k]:
            # Triple at positions x, x+k, x+2k
            # Mark all rectangles [1, x] × [x+2k, n]

            diff[1][x+2*k] += 1
            diff[x+1][x+2*k] -= 1
            diff[1][n+1] -= 1
            diff[x+1][n+1] += 1

# Apply row-wise prefix sums
for r in range(1, n+1):
    for c in range(1, n+1):
        diff[r][c] += diff[r][c-1]

# Apply column-wise prefix sums to get final count
for r in range(1, n+1):
    for c in range(1, n+1):
        diff[r][c] += diff[r-1][c]

print(diff[n][n])
