left_count = 0
right_count = 0
for char in s:
    if char == '(':
        left_count += 1
    else:
        right_count += 1

# Check if we can form a valid regular sequence with max length
# by ensuring at no point do we have more ')' than '(' in the subsequence
used_left = 0
used_right = 0
valid = True
for char in s:
    if char == '(':
        used_left += 1
    else:
        used_right += 1
    if used_right > used_left:
        valid = False
        break

if valid:
    # We can form a valid sequence with max length
    max_length = 2 * min(left_count, right_count)
    print(max_length)
else:
    # We need to find the longest valid parentheses subsequence using a stack
    stack = []
    max_len = 0
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            if stack:
                top = stack.pop()
                current_len = i - top + 1
                max_len = max(max_len, current_len)

    print(max_len)
