def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    idx += 1

    costs = list(map(int, data[idx:idx+n]))
    idx += n

    strings = []
    for _ in range(n):
        strings.append(data[idx])
        idx += 1

    # Compute reversed versions
    reversed_strings = [s[::-1] for s in strings]

    # DP table: dp[i][0] = min energy to reach position i with original string
    #           dp[i][1] = min energy to reach position i with reversed string
    dp = [[float('inf')] * 2 for _ in range(n)]

    # Base case: position 0
    dp[0][0] = 0  # don't reverse first string
    dp[0][1] = costs[0]  # reverse first string

    # Fill DP table
    for i in range(1, n):
        # Try original string at position i
        for prev_choice in [0, 1]:
            if dp[i-1][prev_choice] != float('inf'):
                if strings[i] != strings[prev_choice] and strings[i] >= strings[prev_choice]:
                    dp[i][0] = min(dp[i][0], dp[i-1][prev_choice])
                elif strings[i] == strings[prev_choice]:
                    dp[i][0] = min(dp[i][0], dp[i-1][prev_choice])
        # Try reversed string at position i
        for prev_choice in [0, 1]:
            if dp[i-1][prev_choice] != float('inf'):
                if reversed_strings[i] != reversed_strings[prev_choice] and reversed_strings[i] >= reversed_strings[prev_choice]:
