MOD = 10**9 + 7

def char_to_value(c):
    if '0' <= c <= '9':
        return ord(c) - ord('0')
    elif 'A' <= c <= 'Z':
        return 10 + ord(c) - ord('A')
    elif 'a' <= c <= 'z':
        return 36 + ord(c) - ord('a')
    elif c == '-':
        return 62
    elif c == '_':
        return 63

def count_pairs(s):
    result = 1
    for c in s:
        v = char_to_value(c)
        ones = bin(v).count('1')
        result = result * pow(3, 6 - ones, MOD) % MOD
    return result

s = input().strip()
print(count_pairs(s))
