def is_arithmetic_progression(sequence):
    """Check if a sequence is an arithmetic progression."""
    if len(sequence) < 2:
        return True  # Trivially true for sequences with 1 or 0 elements

    # Calculate the common difference
    common_diff = sequence[1] - sequence[0]

    # Check if all consecutive differences are equal to common_diff
    for i in range(2, len(sequence)):
        if sequence[i] - sequence[i-1] != common_diff:
            return False

    return True

n = int(input())
sequence = list(map(int, input().split()))

if is_arithmetic_progression(sequence):
    # Calculate the next term
    common_diff = sequence[1] - sequence[0]
    next_term = sequence[-1] + common_diff
    print(next_term)
else:
    # The next term is the last term
    print(sequence[-1])
"}

