    n = int(data[0])
    temps = list(map(int, data[1:1+n]))

    # Check if it's an arithmetic progression
    is_ap = True
    diff = temps[1] - temps[0]

    for i in range(2, n):
        if temps[i] - temps[i-1] != diff:
            is_ap = False
            break

    if is_ap:
        print(temps[-1] + diff)
    else:
        print(temps[-1])

if __name__ == "__main__":
    predict_temperature()

