            l_j, r_j = segments[j]

            # Check if segment i covers segment j
            if not (l_i <= l_j and r_j <= r_i):
                covers_all = False
                break

        if covers_all:
            print(i + 1)
            return

    print(-1)

if __name__ == "__main__":
