def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, x = map(int, input().split())
        adj = [[] for _ in range(n + 1)]

        for _ in range(n - 1):
            u, v = map(int, input().split())
            adj[u].append(v)
            adj[v].append(u)

        # If x is a leaf (degree 1)
        if len(adj[x]) == 1:
            results.append("Ayush")
            continue

        # Count the number of nodes that need to be removed
        visited = set()
        stack = [x]
        visited.add(x)

        while stack:
            node = stack.pop()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

        count = len(visited) - 1  # Exclude x itself
        if count % 2 == 1:
            results.append("Ayush")
        else:
            results.append("Ashish")

    print("\n".join(results))

solve()
