def count_perfect_powers(n):
    if n < 2:
        return 0
    perfect_powers = set()

    # Check all possible exponents from 2 to log base 2 of n
    for exponent in range(2, n.bit_length() + 1):
        # Check if 2^exponent exceeds n
        if 2 ** exponent > n:
