def is_prime(n):
    if n < 2:
        return True
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    max_div = int(n**0.5) + 1
    for d in range(3, max_div, 2):
        if n % d == 0:
            return False
    return True

def solve():
    q = int(input().strip())

    # Check if q is 1 or prime
    if q == 1 or is_prime(q):
        print(1)
        print(0)
        return

    # Find a non-trivial divisor of q that is a losing position
    # A losing position is when the number has no non-trivial divisors (i.e., prime or 1)

    # Find the smallest prime factor of q
    if q % 2 == 0:
        print(1)
        print(2)
        return

    for d in range(3, int(q**0.5) + 1, 2):
        if q % d == 0:
            # Check if d is prime
            if is_prime(d):
                print(1)
                print(d)
                return

    # If we didn't find a prime factor, q is a prime (but we already checked that)
    # In this case, the smallest non-trivial divisor is q//2
    print(1)
    print(q // 2)

solve()
"}

