{"code": "
from math import gcd

def solve():
    import sys
    input = sys.stdin.read().split()
    if not input:
        return

    data = iter(input)
    n = int(next(data))
    a = [int(next(data)) for _ in range(n)]

    queries = []
    q = int(next(data))
    for _ in range(q):
        queries.append(int(next(data)))

    # pos_gcds[i] will store GCD counts for subarrays ending at position i
    pos_gcds = []

    # For each element, calculate GCDs of subarrays ending at that element
    for i in range(n):
        new_gcds = {}
        new_gcds[a[i]] = 1  # Single element subarray [a[i]]

        # Combine with previous position's GCDs
        if i > 0:
            prev_gcds = pos_gcds[i-1]
            for prev_gcd, prev_count in prev_gcds.items():
                new_gcd = gcd(prev_gcd, a[i])
                new_gcds[new_gcd] = new_gcds.get(new_gcd, 0) + prev_count

        # Store for this position
        pos_gcds.append(new_gcds)

    # Create a result dictionary for query results
    result = {}

    # Sum up counts from all positions
    for i, gcd_counts in enumerate(pos_gcds):
        for gcd_val, count in gcd_counts.items():
            result[gcd_val] = result.get(gcd_val, 0) + count

    # Process queries
    for x in queries:
        print(result.get(x, 0))

if __name__ == "__main__":
    solve()
"}

