for i in range(1, n + 1):
    for j in range(x + 1):
        # Option 1: select picture i
        if j >= 1:
            dp[i][j] = max(dp[i][j], dp[i-1][j-1] + a[i-1])

        # Option 2: don't select picture i
        if j <= x and dp[i-1][j] != INF:
            # Need at least one selection in positions i-k+1 to i-1
            # We need to look back k-1 positions and ensure there's at least one selection
            # If we don't select i, we can transition from dp[i-k][j] to dp[i][j]
            if i - k >= 0:
                dp[i][j] = max(dp[i][j], dp[i-k][j])
