def solve():
    s = input().strip()
    t = input().strip()

    len_s = len(s)
    len_t = len(t)

    # dp[i]: minimum number of pieces to build first i characters of t
    dp = [float('inf')] * (len_t + 1)
    dp[0] = 0

    # prev[i]: (start_idx, length, reversed) for the last piece
    # This helps reconstruct the solution
    prev = [-1] * (len_t + 1)

    for i in range(len_t + 1):
        if dp[i] == float('inf'):
            continue

        # Try to match substring of s starting at position j
        for j in range(len_s):
            k = 1
            while True:
                next_i = i + k
                if next_i > len_t or j + k >= len_s:
                    break
                if t[next_i - 1] == s[j + k - 1] and dp[next_i] > dp[i] + 1:
                    dp[next_i] = dp[i] + 1
                    prev[next_i] = (j, k, False)
                else:
                    break
                k += 1

            # Match reversed
            k = 1
            while True:
                next_i = i + k
                if next_i > len_t or j + k >= len_s:
                    break
                if t[next_i - 1] == s[len_s - 1 - (j + k - 1)] and dp[next_i] > dp[i] + 1:
                    dp[next_i] = dp[i] + 1
                    prev[next_i] = (j, k, True)
                else:
                    break
                k += 1


    if dp[len_t] == float('inf'):
        print(-1)
    else:
        print(dp[len_t])

        # Reconstruct the solution
        pos = len_t
        res = []
        while pos > 0:
            j, k, reversed_flag = prev[pos]
            start_idx = j + 1  # 1-indexed
            end_idx = j + k
            if reversed_flag:
                res.append((start_idx, end_idx))
            else:
                res.append((start_idx, end_idx))
            pos -= k

        for x, y in res[::-1]:  # Reverse to get order
            print(x, y)

solve()
