import sys

def solve():
    lines = sys.stdin.read().strip().split('\n')

    # Parse descriptions
    descriptions = []
    for line in lines:
        if line.startswith('A.') or line.startswith('B.') or line.startswith('C.') or line.startswith('D.'):
            # Extract description (everything after the prefix)
            prefix_len = len(line.split('.')[0]) + 1  # 1 for the period
            desc = line[prefix_len:].strip()
            descriptions.append(desc)

    # Get lengths
    lengths = [len(desc) for desc in descriptions]

    # Find great choices
    great_choices = []
    for i in range(4):
        length = lengths[i]
        great = True

        # Check if length is at least twice shorter than all others
        if not all(length <= other_length / 2 for other_length in lengths if other_length != length):
            great = False

        # Check if length is at least twice longer than all others
        if not all(length >= 2 * other_length for other_length in lengths if other_length != length):
            great = False

        if great:
            great_choices.append(i)

    # Determine child's choice
    if len(great_choices) == 1:
        return chr(ord('A') + great_choices[0])
    else:
        return 'C'

if __name__ == '__main__':
    print(solve())
