import sys

def solve():
    MOD = 10**9 + 7
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        arr = [int(next(it)) for _ in range(n)]

        # Precompute bit counts
        cnt = [0] * 60
        for num in arr:
            for i in range(60):
                if num & (1 << i):
                    cnt[i] += 1

        result = 0
        for j in range(n):
            # Compute sum_{i} (x_i & x_j)
            s_and = 0
            for i in range(60):
                if arr[j] & (1 << i):
                    s_and += (cnt[i] - 1) * (1 << i)

            # Compute sum_{k} (x_j | x_k)
            s_or = 0
            for i in range(60):
                if arr[j] & (1 << i):
                    s_or += n * (1 << i)
                else:
                    s_or += cnt[i] * (1 << i)

            result += s_and * s_or
            result %= MOD

        print(result % MOD)

if __name__ == "__main__":
    solve()
