for _ in range(t):
    # Skip empty lines
    while True:
        try:
            if next(data).strip() == "":
                continue
        except StopIteration:
            break

    n = int(next(data))
    m = int(next(data))

    c = [int(next(data)) for _ in range(m)]

    # For each left vertex, store its connected right vertices
    left_adj = [[] for _ in range(n)]

    for _ in range(m):
        u = int(next(data)) - 1  # 0-indexed
        v = int(next(data)) - 1  # 0-indexed
        left_adj[u].append(v)

    # Compute sum for each left vertex
    sums = []
    for u in range(n):
        s = sum(c[v] for v in left_adj[u])
        sums.append(s)

    # Compute GCD
    result = gcd_list(sums)

    print(result)
