def cross(o1, o2, o3):
    """Check if line segment o1-o2 crosses o3."""
    # Check if o3 is on the line segment o1-o2
    if (o2[0] - o1[0]) * (o3[1] - o1[1]) == (o3[0] - o1[0]) * (o2[1] - o1[1]):
