def is_lexicographically_smaller(a, b):
    """Check if string a is lexicographically smaller than or equal to string b"""
    return a <= b

def solve():
    n = int(input())
    costs = list(map(int, input().split()))
    strings = [input().strip() for _ in range(n)]

    # For each position, we track the minimum cost to reach that state
    # state 0: string at position i is not reversed
    # state 1: string at position i is reversed
    dp = [float('inf')] * 2

    for i in range(n):
        # For the current string, we have two options
        original = strings[i]
        reversed_str = strings[i][::-1]

        # Try to transition to state 0 (not reversed)
        if i == 0:
            # First string, no previous
            dp[0] = 0
        else:
            # Check if original string is valid
            if is_lexicographically_smaller(original, strings[i-1]):
                dp[0] = min(dp[0], dp[0] + 0)  # No cost to not reverse

        # Try to transition to state 1 (reversed)
        if i == 0:
            # First string, no previous
            dp[1] = 0
        else:
            # Check if reversed string is valid
            if is_lexicographically_smaller(reversed_str, strings[i-1]):
                dp[1] = min(dp[1], dp[1] + costs[i])  # Add cost to reverse


    # Check if any state is still infinity
    if dp[0] == float('inf') and dp[1] == float('inf'):
        print(-1)
    else:
        print(min(dp))

solve()
