            # If no pizzas needed today, we can't use any coupons that land today
            # So we must have 0 coupons in transit from previous day
            dp[i] = {0: True}
            continue

        dp[i] = {}

        # Check all possible states from previous day
        for prev_coupons, can_reach in dp[i-1].items():
            if not can_reach:
                continue

            # Option 1: Use some coupons that land today
            # Each coupon that lands today uses 1 pizza from today
            max_landing_coupons = a[i-1] - prev_coupons
            if max_landing_coupons < 0:
                continue

            # Option 2: Use discount 1 (needs even number of pizzas)
            if a[i-1] % 2 == 0:
                # Use discount 1 on all pizzas today
                coupons_after = prev_coupons
                if coupons_after not in dp[i]:
