                if remaining < 0:
                    continue
                if remaining % 2 == 0:
                    coupons_after = prev_coupons
                    if coupons_after not in dp[i]:
                        dp[i][coupons_after] = True


    # After day n, we must have 0 coupons in transit
    print("YES" if 0 in dp[n] else "NO")

