def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # dp[i][j]: True if we can satisfy days 1..i with j coupons in transit from day i to day i+1
    dp = [{} for _ in range(n+1)]
    dp[0][0] = True  # Initially, no coupons in transit

    for i in range(1, n+1):
        dp[i] = {}

        # Check all possible states from previous day
        for prev_coupons, can_reach in dp[i-1].items():
            if not can_reach:
                continue

            # Option 1: Use some coupons that land today (from day i-1 to day i)
            # These coupons take off from day i, so they use 1 pizza from day i
            max_landing_coupons = a[i-1] - prev_coupons
            if max_landing_coupons >= 0:
                # Use k coupons that land today (k >= 1)
                for k in range(1, max_landing_coupons + 1):
                    remaining = a[i-1] - k
                    if remaining % 2 == 0:
                        # After using k landing coupons and some discount 1, we have no remaining pizza
                        coupons_after = 0
                        if coupons_after not in dp[i]:
                            dp[i][coupons_after] = True

            # Option 2: Use some coupons that take off today (to day i+1)
            # These coupons land on day i and take off from day i
            # They use 1 pizza from day i and create 1 coupon in transit
            max_taking_off_coupons = a[i-1] - prev_coupons
            if max_taking_off_coupons >= 0:
                # Use k coupons that take off today (k >= 1)
                for k in range(1, max_taking_off_coupons + 1):
