def solve():
    s = input().strip()
    t = input().strip()

    n = len(t)
    m = len(s)

    # DP: dp[i] = minimum number of pieces to match t[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    # prev[i] = (start, start_in_s, length, reversed)
    prev = [-1] * (n + 1)

    for i in range(n + 1):
        if dp[i] == float('inf'):
            continue

        # Try all possible lengths for the next piece
        for length in range(1, n - i + 1):
            target = t[i:i+length]

            # Try all possible substrings of s
            for l in range(len(s) - length + 1):
                if s[l:l+length] == target:
                    if dp[i+length] > dp[i] + 1:
                        dp[i+length] = dp[i] + 1
                        prev[i+length] = (i, l, length, False)
                    break

            # Try all possible substrings of s (reversed)
            for l in range(len(s) - length + 1):
                if s[l:l+length][::-1] == target:
                    if dp[i+length] > dp[i] + 1:
                        dp[i+length] = dp[i] + 1
                        prev[i+length] = (i, l, length, True)
                    break

    if dp[n] == float('inf'):
        print(-1)
    else:
        print(dp[n])

        # Reconstruct the path
        path = []
        i = n
        while i > 0:
            if prev[i] == -1:
                break
            start, start_in_s, length, reversed = prev[i]
            path.append((start, start_in_s, length, reversed))
            i = start

        # Print the path in reverse order (from first piece to last)
        for item in reversed(path):
            start, start_in_s, length, reversed = item
            if reversed:
                print(start_in_s + 1, start_in_s + length)
            else:
                print(start + 1, start + length)

solve()
