        n, x = map(int, input().split())
        s = input().strip()

        zero_count = s.count('0')
        one_count = n - zero_count
        balance_per_copy = zero_count - one_count

        # Precompute prefix balances
        prefix_balances = [0]
        balance = 0
        for ch in s:
            balance += 1 if ch == '0' else -1
            prefix_balances.append(balance)

        # If balance of one copy is 0, check if x matches any prefix balance
        if balance_per_copy == 0:
            # Check if x is in prefix_balances
            if x in prefix_balances:
                print(-1)  # Infinite prefixes
            else:
                print(0)
        else:
            # Count how many prefix balances can reach x
            count = 0
            for b in prefix_balances:
                # Solve k * balance_per_copy + b = x
                # k = (x - b) / balance_per_copy
                if (x - b) % balance_per_copy == 0:
                    k = (x - b) // balance_per_copy
                    if k >= 0:
                        count += 1
            print(count)

