import sys
import math

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    q = int(next(it))
    queries = [int(next(it)) for _ in range(q)]

    # cnt[x] = number of subarrays with GCD x
    cnt = {}

    # For each position, track GCD values of subarrays ending there
    prev_gcds = {}

    for num in a:
        curr_gcds = {}
        # Consider subarrays ending at previous position
        for gcd_val, count in prev_gcds.items():
            new_gcd = math.gcd(gcd_val, num)
            curr_gcds[new_gcd] = curr_gcds.get(new_gcd, 0) + count

        # Consider subarray consisting of just this element
        curr_gcds[num] = curr_gcds.get(num, 0) + 1

        # Update overall count
        for gcd_val, count in curr_gcds.items():
            cnt[gcd_val] = cnt.get(gcd_val, 0) + count

        prev_gcds = curr_gcds

    # Process queries
    for x in queries:
        print(cnt.get(x, 0))

if __name__ == "__main__":
    solve()
