def is_winning(n, memo):
    """Check if n is a winning position."""
    if n in memo:
        return memo[n]

    # Find all non-trivial divisors of n
    divisors = []
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            if i != n // i:
                divisors.append(i)
                divisors.append(n // i)
            else:
                divisors.append(i)

    # Check if all non-trivial divisors are winning
    # If at least one is losing, then n is winning
    # If all are winning, then n is losing
    is_winning = False
    for d in divisors:
        if not is_winning:
            is_winning = not is_winning(d, memo)

    memo[n] = is_winning
    return is_winning

def solve(q):
    memo = {1: True}  # 1 is winning (no moves)

    # Check if q is winning
    q_winning = is_winning(q, memo)

    if q_winning:
        # Find any non-trivial divisor that is losing
        for d in range(2, int(q ** 0.5) + 1):
            if q % d == 0:
                if d != q // d:
                    if not is_winning(d, memo):
                        return (1, d)
                    if not is_winning(q // d, memo):
                        return (1, q // d)
                else:
                    if not is_winning(d, memo):
                        return (1, d)
        return (1, 0)  # Should never happen
    else:
        # q is losing, player 2 wins
        return (2, 0)

