def solve():
    n = int(input())

    # Count chains (bases) with at least one power <= n
    # Base 1: just {1}
    chains = 1  # base 1 chain

    # For bases from 2 to n, count how many powers of b are <= n
    b = 2
    while b <= n:
        # Count powers of b: b, b^2, b^3, ... <= n
        power = b
        count = 0
        while power <= n:
            count += 1
            power *= b
        if count > 0:
            chains += 1
        b += 1

    # XOR of 1s (each chain contributes 1)
    xor_sum = 1
    for _ in range(chains - 1):
        xor_sum ^= 1

    if xor_sum == 0:
        print("Petya")
    else:
        print("Vasya")

solve()
