    t = input().strip()

    n, m = len(t), len(s)

    # dp[i][j] = minimum number of pieces to build t[:i] using s[:j]
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # Option 1: take a single character from s[j-1]
            if t[i-1] == s[j-1]:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1])

            # Option 2: take a substring ending at position j in s
            for k in range(1, j + 1):
                # Check if we can take a substring of length k ending at j in s
                # and match it with the corresponding part of t
                if t[i-k:i] == s[j-k:j] or t[i-k:i] == s[j-k:j][::-1]:
                    dp[i][j] = min(dp[i][j], dp[i-k][j-k] + 1)

    if dp[n][m] == float('inf'):
        print(-1)
    else:
        print(dp[n][m])

solve()
