def solve():
    MOD = 10**9 + 7
    t = int(input())

    for _ in range(t):
        n = int(input())
        x = list(map(int, input().split()))

        # Count bits
        count = [0] * 60
        for num in x:
            for b in range(60):
                if num & (1 << b):
                    count[b] += 1

        total = 0
        for j in range(n):
            # Compute A = sum_i (x_i & x[j])
            # Compute B = sum_k (x[j] | x[k])
            # Then contribution = A * B

            A = 0
            B = 0
            for b in range(60):
                if x[j] & (1 << b):
                    # Bit b is set in x[j]
                    A += count[b] * (1 << b)
                    B += n * (1 << b)
                else:
                    # Bit b is not set in x[j]
                    B += count[b] * (1 << b)

            contribution = A * B
            total = (total + contribution) % MOD

        print(total)

solve()
