noun_count = 0
verb_count = 0
valid_pattern = True

for part in parts:
    if part == "adjective":
        adj_count += 1
    elif part == "noun":
        noun_count += 1
    elif part == "verb":
        verb_count += 1
    else:
        # Invalid part of speech
        valid_pattern = False
        break

if not valid_pattern or noun_count != 1:
