def solve():
    n = int(input())
    s = input()

    # For each position, choose a color that is different from both neighbors
    t = list(s)

    for i in range(n):
        prev = t[i-1] if i > 0 else None
        next_color = s[i+1] if i < n-1 else None

        # Choose a color different from both neighbors
        if prev is not None and next_color is not None:
            if prev != next_color:
                # Two different colors, we need the third
                for c in ['R', 'G', 'B']:
                    if c != prev and c != next_color:
                        t[i] = c
                        break
            else:
                # Both are the same, we can choose either of the other two
                for c in ['R', 'G', 'B']:
                    if c != prev:
                        t[i] = c
                        break
        elif prev is not None:
            # Only previous exists, choose different from previous
            for c in ['R', 'G', 'B']:
                if c != prev:
                    t[i] = c
                    break
        elif next_color is not None:
            # Only next exists, choose different from next
            for c in ['R', 'G', 'B']:
                if c != next_color:
                    t[i] = c
                    break
        else:
            # First position, choose any color
            t[i] = 'R'  # arbitrary choice

    # Count recolors
    recolors = sum(1 for i in range(n) if t[i] != s[i])

    print(recolors)
    print(''.join(t))

solve()
