# Classify words
valid_words = []
for word in words:
    if word.endswith("lios"):
        valid_words.append(("adjective", "masculine"))
    elif word.endswith("liala"):
        valid_words.append(("adjective", "feminine"))
    elif word.endswith("etr"):
        valid_words.append(("noun", "masculine"))
    elif word.endswith("etra"):
        valid_words.append(("noun", "feminine"))
    elif word.endswith("initis"):
        valid_words.append(("verb", "masculine"))
    elif word.endswith("inites"):
        valid_words.append(("verb", "feminine"))
    else:
        # Invalid word
        valid_words = None
        break

if valid_words is None:
    print("NO")
else:
    if len(valid_words) == 1:
        print("YES")
    else:
        # Check if all words have the same gender
        gender = valid_words[0][1]
        all_same_gender = all(word[1] == gender for word in valid_words)

        if not all_same_gender:
            print("NO")
        else:
            # Check order: adjectives (0+) + noun (1) + verbs (0+)
            # Find the position of the noun
            noun_pos = -1
            for i, (part, g) in enumerate(valid_words):
                if part == "noun":
                    noun_pos = i
                    break

            if noun_pos == -1:
                # No noun found
                print("NO")
            else:
                # Check all words before noun are adjectives
                valid_order = all(part == "adjective" for i, (part, g) in enumerate(valid_words) if i < noun_pos)

                # Check all words after noun are verbs
                valid_order &= all(part == "verb" for i, (part, g) in enumerate(valid_words) if i > noun_pos)

                if valid_order:
                    print("YES")
                else:
                    print("NO")
