import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Use a stack where each element is (value, count)
    stack = []

    for num in a:
        if stack and stack[-1][0] == num:
            # Merge with previous element
            val, count = stack.pop()
            if count + 1 >= 2:
                # Merge again (count+1 >= 2 means we have at least two elements)
                stack.append((val + 1, count + 1))
            else:
                stack.append((val, count + 1))
        else:
            stack.append((num, 1))

    # Format output
    print(len(stack))
    print(' '.join(str(val) for val, _ in stack))

if __name__ == "__main__":
    solve()
"}

