def weird_subtraction(n, m):
    a = n
    b = m

    while a > 0 and b > 0:
        if a >= 2 * b:
            # Subtract 2*b from a multiple times
            quotient = a // (2 * b)
            remainder = a % (2 * b)
            a = remainder
        elif b >= 2 * a:
            # Subtract 2*a from b multiple times
            quotient = b // (2 * a)
            remainder = b % (2 * a)
            b = remainder
        else:
